/// <summary>
/// Data contract class for service <c>METSalesOrderCancelService</c>
/// </summary>
[DataContractAttribute]
public class METSalesOrderCancelRequestContract
{
    DataAreaId  dataAreaId;
    SalesId     salesId;
    
}

Method.Source:
/// <summary>
/// Gets/sets the company ID
/// </summary>
/// <param name = "_dataAreaId">company ID</param>
/// <returns>returns the company ID</returns>
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _dataAreaId = dataAreaId)
{
    dataAreaId = _dataAreaId;
    return dataAreaId;
}

/// <summary>
/// Gets/sets the sales order number
/// </summary>
/// <param name = "_salesId">sales order number</param>
/// <returns>return the sales order number</returns>
[DataMemberAttribute('SalesOrderNumber')]
public SalesId parmSalesId(SalesId _salesId = salesId)
{
    salesId = _salesId;
    return salesId;
}

/// <summary>
/// Instantiate new object
/// </summary>
/// <returns>The new object</returns>
public static METSalesOrderCancelRequestContract construct()
{
    return new METSalesOrderCancelRequestContract();
}
